import json
from itertools import combinations

BLD = ["Garza", "Yates", "Zimmer", "Flores", "Lynch", "King", "Meyer", "Ortiz"]
CLS = {"Garza": 1, "Flores": 1, "Yates": 3, "Zimmer": 3,
       "Lynch": 2, "King": 2, "Meyer": 2, "Ortiz": 2}
INIT = {"Garza": "RealProp", "Yates": "RealProp", "Zimmer": "RealProp",
        "Flores": "Southco", "Lynch": "Southco",
        "King": "Trustcorp", "Meyer": "Trustcorp", "Ortiz": "Trustcorp"}
COS = ["RealProp", "Southco", "Trustcorp"]

# Allowed trade shapes (class patterns of the two sides, sorted), either direction:
# one-for-one same class; class1 for two class2; class2 for two class3.
VALID = {((1,), (1,)), ((2,), (2,)), ((3,), (3,)),
         ((1,), (2, 2)), ((2, 2), (1,)),
         ((2,), (3, 3)), ((3, 3), (2,))}

def subsets(items):
    for r in (1, 2):
        for c in combinations(items, r):
            yield c

start = tuple(INIT[b] for b in BLD)
seen = {start}
queue = [start]

while queue:
    st = queue.pop()
    own = dict(zip(BLD, st))
    for p in COS:
        for q in COS:
            if p == q:
                continue
            lp = [b for b in BLD if own[b] == p]
            lq = [b for b in BLD if own[b] == q]
            for X in subsets(lp):
                for Y in subsets(lq):
                    key = (tuple(sorted(CLS[x] for x in X)),
                           tuple(sorted(CLS[y] for y in Y)))
                    if key not in VALID:
                        continue
                    new = dict(own)
                    for x in X:
                        new[x] = q
                    for y in Y:
                        new[y] = p
                    ns = tuple(new[b] for b in BLD)
                    if ns not in seen:
                        seen.add(ns)
                        queue.append(ns)

OPT = {
    "A": ("RealProp", {"Lynch", "Meyer", "Ortiz"}),
    "B": ("Southco", {"Garza", "Meyer"}),
    "C": ("Southco", {"King", "Meyer", "Ortiz"}),
    "D": ("Trustcorp", {"Flores", "Yates"}),
    "E": ("Trustcorp", {"Garza", "Lynch"}),
}

def possible(company, buildings):
    target = frozenset(buildings)
    for st in seen:
        owned = frozenset(b for b, o in zip(BLD, st) if o == company)
        if owned == target:
            return True
    return False

possible_map = {k: possible(c, s) for k, (c, s) in OPT.items()}
impossible = [k for k, v in possible_map.items() if not v]

final = impossible[0] if len(impossible) == 1 else "UNSUPPORTED"

result = {
    "final_answer": final,
    "evidence": {
        "reachable_states": len(seen),
        "possible": possible_map,
        "impossible": impossible,
    },
}
print(json.dumps(result, separators=(",", ":")))
